DROP TABLE IF EXISTS `md_io_template_field`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_io_template_field` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID【多租户隔离字段】',
  `template_id` bigint NOT NULL COMMENT '所属模板 md_io_template.id',
  `field_key` varchar(64) NOT NULL COMMENT '库字段名(实体属性名,驼峰)',
  `column_name` varchar(128) NOT NULL COMMENT 'Excel 列头文案(用户可见)',
  `column_type` varchar(16) NOT NULL DEFAULT 'STRING' COMMENT '数据类型:STRING/NUMBER/DATE/DATETIME/BOOLEAN/ENUM',
  `db_column` varchar(64) DEFAULT NULL COMMENT '数据库列名(默认取 field_key 驼峰转下划线)',
  `required` tinyint NOT NULL DEFAULT '0' COMMENT '必录:1-是(缺值该行报错)',
  `dict_type` varchar(64) DEFAULT NULL COMMENT '字典类型(ENUM 时校验取值,如 bill_status)',
  `enum_values` varchar(500) DEFAULT NULL COMMENT '枚举可选值(逗号分隔,ENUM 且无字典时生效)',
  `ref_table` varchar(64) DEFAULT NULL COMMENT '参照表(如 REF 类型:按 code 查 name 回填 id)',
  `ref_code_col` varchar(64) DEFAULT NULL COMMENT '参照表的编码列',
  `ref_name_col` varchar(64) DEFAULT NULL COMMENT '参照表的名称列',
  `default_value` varchar(200) DEFAULT NULL COMMENT '缺省值(该列为空时写入)',
  `max_length` int DEFAULT NULL COMMENT '最大长度(超长报错,替代各 Service 手写校验)',
  `decimal_scale` int DEFAULT NULL COMMENT '小数位(金额列)',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '列序',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注/取值说明(导入失败时回显给用户)',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_iof_tpl_key` (`template_id`,`field_key`),
  KEY `idx_iof_tenant_tpl` (`tenant_id`,`template_id`),
  KEY `idx_iof_tpl_sort` (`template_id`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=172 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='导入导出模板字段定义（列头文案↔库字段映射+声明式转换规则）';
/*!40101 SET character_set_client = @saved_cs_client */;

